{{ config(materialized='table') }}

with
quarantined as (
    select
        order_status,
        currency,
        channel,
        source_record_id,
        source_order_id,
        source_customer_id,
        order_date,
        order_total,
        source_system,
        order_value_band,
        customer_business_key,
        violation_00,
        violation_01
    from {{ ref("ecommerce__order__checked_pre") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        order_status,
        currency,
        channel,
        source_record_id,
        source_order_id,
        source_customer_id,
        order_date,
        order_total,
        source_system,
        order_value_band,
        customer_business_key
    from quarantined
    where violation_00

    union all

    select
        'source_order_id_not_null' as rule_name,
        order_status,
        currency,
        channel,
        source_record_id,
        source_order_id,
        source_customer_id,
        order_date,
        order_total,
        source_system,
        order_value_band,
        customer_business_key
    from quarantined
    where violation_01
)

select
    rule_name,
    order_status,
    currency,
    channel,
    source_record_id,
    source_order_id,
    source_customer_id,
    order_date,
    order_total,
    source_system,
    order_value_band,
    customer_business_key
from violations
